import pandas as pd,numpy as np
from sklearn.ensemble import RandomForestRegressor,ExtraTreesRegressor,GradientBoostingRegressor
from sklearn.model_selection import KFold
f=pd.read_csv('frac.csv')
vars='O Cu Ba Sr Y Ca La Bi Fe Nb C Pr As B Pb Ce Mo V Zn Ni'.split()
ub=np.array([0.697674,0.454545,0.333333,0.285714,0.4,0.272727,0.78,0.521978,0.502513,0.98,0.972,0.265043,0.5,1,0.5,0.28,1,0.9918,1,0.6])
X=f[vars].values; y=f.target.values
msA=[];msB=[]
for seed in range(3):
    for tr,_ in KFold(5,shuffle=True,random_state=seed).split(X):
        msA.append(RandomForestRegressor(200,random_state=seed).fit(X[tr],y[tr]))
        msA.append(GradientBoostingRegressor(random_state=seed).fit(X[tr],y[tr]))
for seed in range(10,13):
    for tr,_ in KFold(5,shuffle=True,random_state=seed).split(X):
        msB.append(ExtraTreesRegressor(200,random_state=seed).fit(X[tr],y[tr]))
        msB.append(RandomForestRegressor(300,max_features=0.5,random_state=seed).fit(X[tr],y[tr]))
def mk(ms):
    def pred(P): P=np.atleast_2d(P); return np.mean([m.predict(P) for m in ms],axis=0)
    return pred
pA,pB=mk(msA),mk(msB)
def pts_of(x):
    pts=[x]
    for i in range(20):
        for s in (0.95,1.05):
            z=x.copy(); z[i]=min(z[i]*s,ub[i]); pts.append(z)
        for s in (-0.05,0.05):
            z=x.copy(); z[i]=np.clip(z[i]+s*ub[i],0,ub[i]); pts.append(z)
    return np.array(pts)
def obj(x,pred):
    v=pred(pts_of(x)); return 0.5*v.min()+0.5*v.mean()
rng=np.random.default_rng(1)
cands=list(X)+[rng.uniform(0,1,20)*ub*(rng.random((20,))<0.3) for _ in range(4000)]
best=sorted(((obj(np.array(c),pA),np.array(c)) for c in cands),key=lambda t:-t[0])[:12]
for it in range(80):
    new=[]
    for sc,x in best:
        for _ in range(40):
            z=x.copy()
            for i in rng.choice(20,rng.integers(1,4),replace=False):
                z[i]=np.clip(z[i]+rng.normal(0,0.06)*ub[i],0,ub[i])
                if rng.random()<0.25: z[i]=0.0
            new.append(z)
    best=sorted(((obj(x,pA),x) for x in [b[1] for b in best]+new),key=lambda t:-t[0])[:12]
print('objA',round(best[0][0],2))
for sc,x in best[:6]:
    vA=pA(pts_of(x)); vB=pB(pts_of(x))
    print(f'A nom{vA[0]:6.1f} min{vA.min():6.1f} | B nom{vB[0]:6.1f} min{vB.min():6.1f}', {v:round(q,4) for v,q in zip(vars,x) if q>1e-4})
np.save('best2.npy',best[0][1])
